/**
 * Notifikasi global (toast) — dipakai di SELURUH portal untuk menampilkan pesan
 * error / sukses / info yang informatif.
 *
 * Cara pakai:
 *   import { notifyError, notifySuccess, notifyInfo } from '../composables/toast'
 *   try { ... } catch (e) { notifyError(e, 'Gagal menyimpan') }
 *   notifySuccess('Berhasil disimpan')
 *
 * Komponen <Toasts /> (dipasang di App.vue) merender tumpukannya. Selain
 * dipanggil manual, notifyError juga dipicu OTOMATIS oleh:
 *   - resourceFetcher (setiap request frappe-ui yang gagal) di main.js
 *   - app.config.errorHandler (error render/komponen Vue) di main.js
 *   - window 'unhandledrejection' & 'error' di main.js
 */
import { reactive } from 'vue'

export const toasts = reactive([])

let _id = 0
// Anti-spam: pesan identik yang muncul beruntun dalam jendela waktu ini
// (mis. resourceFetcher + catch halaman melaporkan error yang sama) hanya
// ditampilkan sekali.
//
// JUDUL SENGAJA TIDAK IKUT jadi kunci. Satu kegagalan bisa dilaporkan beberapa
// lapis dengan judul berbeda-beda: resourceFetcher memakai "Gagal memuat data"
// lalu melempar ulang errornya, dan lemparan yang tidak tertangkap ditangkap
// lagi oleh handler unhandledrejection dengan judul "Terjadi kesalahan".
// Isinya sama persis, jadi bagi pembaca itu satu kejadian — bukan dua.
const DEDUPE_MS = 4000
const _recent = new Map() // signature → timestamp

const DURATION = { error: 8000, success: 3500, info: 4500 }

function _push(type, title, message) {
	const sig = `${type}|${message}`
	const now = Date.now()
	const last = _recent.get(sig)
	if (last && now - last < DEDUPE_MS) return null
	_recent.set(sig, now)
	// Bersihkan cache dedupe sesekali supaya tidak tumbuh terus.
	if (_recent.size > 50) {
		for (const [k, t] of _recent) if (now - t > DEDUPE_MS) _recent.delete(k)
	}

	const id = ++_id
	toasts.push({ id, type, title, message })
	const ttl = DURATION[type] || 5000
	setTimeout(() => dismissToast(id), ttl)
	return id
}

export function dismissToast(id) {
	const i = toasts.findIndex((t) => t.id === id)
	if (i !== -1) toasts.splice(i, 1)
}

/**
 * Ekstrak pesan yang bisa dibaca manusia dari bentuk error apa pun:
 * Error object, string, response frappe-ui/fetch (_server_messages, exc,
 * messages, message), atau objek JSON error Frappe.
 */
export function errorMessage(err) {
	if (!err) return 'Terjadi kesalahan yang tidak diketahui.'
	if (typeof err === 'string') return _stripHtml(err)

	// frappe-ui/frappeRequest & Frappe REST → daftar pesan server yang ramah.
	const fromServerMessages = _parseServerMessages(err._server_messages)
	if (fromServerMessages) return fromServerMessages

	// frappe-ui sering menaruh pesan terparse di err.messages (array).
	if (Array.isArray(err.messages) && err.messages.length) {
		return err.messages.map((m) => _stripHtml(String(m))).join('\n')
	}

	// Traceback server (exc) → ambil baris terakhir yang bermakna.
	if (err.exc) {
		const line = _lastMeaningfulLine(err.exc)
		if (line) return _stripHtml(line)
	}
	if (err.exception) return _stripHtml(String(err.exception))

	// Objek Error / response biasa.
	if (err.message) {
		// Kadang err.message berisi JSON dari fetch → coba parse dulu.
		const nested = _tryParseJsonError(err.message)
		if (nested) return nested
		return _stripHtml(String(err.message))
	}

	try {
		return _stripHtml(JSON.stringify(err))
	} catch (e) {
		return 'Terjadi kesalahan yang tidak diketahui.'
	}
}

function _parseServerMessages(raw) {
	if (!raw) return ''
	try {
		const arr = typeof raw === 'string' ? JSON.parse(raw) : raw
		if (!Array.isArray(arr) || !arr.length) return ''
		return arr
			.map((m) => {
				try {
					const o = typeof m === 'string' ? JSON.parse(m) : m
					return _stripHtml(o.message || o.title || String(m))
				} catch (e) {
					return _stripHtml(String(m))
				}
			})
			.filter(Boolean)
			.join('\n')
	} catch (e) {
		return ''
	}
}

function _tryParseJsonError(str) {
	const s = String(str).trim()
	if (!s.startsWith('{') && !s.startsWith('[')) return ''
	try {
		const o = JSON.parse(s)
		return _parseServerMessages(o._server_messages) || (o.message ? _stripHtml(o.message) : '')
	} catch (e) {
		return ''
	}
}

function _lastMeaningfulLine(exc) {
	const lines = String(exc)
		.split('\n')
		.map((l) => l.trim())
		.filter(Boolean)
	for (let i = lines.length - 1; i >= 0; i--) {
		if (!/^File "|^Traceback|^\s*\^+\s*$/.test(lines[i])) return lines[i]
	}
	return lines[lines.length - 1] || ''
}

function _stripHtml(s) {
	return String(s)
		.replace(/<[^>]*>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
}

/** Tampilkan notifikasi error. `err` bisa Error/string/response; `title` opsional. */
export function notifyError(err, title = 'Terjadi kesalahan') {
	const message = errorMessage(err)
	// Log penuh ke console untuk debugging (tetap tampilkan versi ramah ke user).
	// eslint-disable-next-line no-console
	console.error(title + ':', err)
	return _push('error', title, message)
}

export function notifySuccess(message, title = 'Berhasil') {
	return _push('success', title, message)
}

export function notifyInfo(message, title = '') {
	return _push('info', title, message)
}
