// Base history: build mobile (bundel lokal) di-serve dari root '/', build web
// portal di-serve dari '/portal/'.
const router = createRouter({
	history: createWebHistory(import.meta.env.VITE_MOBILE ? '/' : '/portal/'),
	routes,
})

// Halaman yang boleh dibuka tanpa login.
const GUEST_ROUTES = ['Login', 'ForgotPassword']

// Route guard: paksa ke login kalau belum auth
router.beforeEach((to, from, next) => {
	const isLoggedIn = session.isLoggedIn
	const isGuestRoute = GUEST_ROUTES.includes(to.name)
	if (!isGuestRoute && !isLoggedIn) {
		next({ name: 'Login' })
	} else if (isGuestRoute && isLoggedIn) {
		next({ name: 'Home' })
	} else {
		next()
	}
})

export default router
