/**
 * Polyfill API JavaScript modern untuk mesin browser/WebView lama.
 *
 * WAJIB di-import PALING AWAL di main.js — sebelum import lain — supaya sudah
 * terpasang saat pustaka yang membutuhkannya dievaluasi.
 */

// Promise.withResolvers (ES2024). Dipakai internal oleh pdfjs-dist v4; tanpa ini
// pembukaan PDF gagal dengan "Promise.withResolvers is not a function".
// Baru tersedia di Chrome/Android WebView 119+, Safari 17.4+, Firefox 121+ —
// jadi perangkat dengan WebView/browser lebih lama (termasuk HP baru yang
// WebView-nya belum ter-update, Samsung Internet lama, in-app browser, atau
// iOS < 17.4) tetap membutuhkan polyfill ini.
if (typeof Promise.withResolvers !== 'function') {
	Promise.withResolvers = function withResolvers() {
		let resolve
		let reject
		const promise = new Promise((res, rej) => {
			resolve = res
			reject = rej
		})
		return { promise, resolve, reject }
	}
}
